public final void addAdapterPPT(@NotNull String path, int width, int height, int viewWidth, int viewHeight, @NotNull r6.c callBack) throws IOException {
    k.g(path, "path");
    k.g(callBack, "callBack");
    if (this.graphControl.getRootGraph().childTypeNumber(WebViewGraph.class.getName()) >= this.sketchConfig.getMaxPPTCount()) {
        Context context = this.context;
        ToastUtils.showShort(context, context.getString(R.string.tips_max_ppt, Integer.valueOf(this.sketchConfig.getMaxPPTCount())));
        return;
    }
    File file = new File(path);
    if (!file.exists()) {
        Context context2 = this.context;
        ToastUtils.showShort(context2, context2.getString(R.string.tips_file_not_found));
        return;
    }
    FileUtils.Companion companion = FileUtils.INSTANCE;
    String absolutePath = file.getParentFile().getAbsolutePath();
    k.f(absolutePath, "file.parentFile.absolutePath");
    String absolutePath2 = new File(this.graphControl.getBasePPTPath()).getParentFile().getAbsolutePath();
    k.f(absolutePath2, "File(graphControl.getBas…).parentFile.absolutePath");
    companion.copyFolder(absolutePath, absolutePath2);
    ActionRecordExecute actionRecordExecute = this.actionExecute;
    ActionRecord actionRecord = this.actionRecord;
    long jCurrentTimeMillis = System.currentTimeMillis();
    String name = file.getName();
    k.f(name, "file.name");
    actionRecordExecute.onAddPPTEvent(actionRecord.buildWebViewData(jCurrentTimeMillis, name, width, height, viewWidth, viewHeight), callBack);
}
